widgets.module_source:
(() => {
  // src/widgets/missing.ts
  var WHY = {
    "repository-required": "Choose a repository for this tile",
    "not-found": "That repository is not there, or not visible to the plug-in",
    "not-authorized": "The organization has not granted the plug-in this"
  };
  function missing(values) {
    const why = values.unavailable;
    if (!why) return null;
    return { v: 1, scene: { kind: "empty", message: WHY[why] || "There is nothing to show" } };
  }

  // src/widgets/open-issues.ts
  function render(data) {
    const nothing = missing(data.values);
    if (nothing) return nothing;
    const total = data.values.total;
    return { v: 1, scene: { kind: "metric", value: typeof total === "number" ? total : data.rows.length, label: "Open issues" } };
  }

  // widget.js
  globalThis.render = render;
})();

(() => {
  // src/widgets/missing.ts
  var WHY = {
    "repository-required": "Choose a repository for this tile",
    "not-found": "That repository is not there, or not visible to the plug-in",
    "not-authorized": "The organization has not granted the plug-in this"
  };
  function missing(values) {
    const why = values.unavailable;
    if (!why) return null;
    return { v: 1, scene: { kind: "empty", message: WHY[why] || "There is nothing to show" } };
  }

  // src/widgets/review-queue.ts
  function render(data) {
    const nothing = missing(data.values);
    if (nothing) return nothing;
    if (!data.rows.length) return { v: 1, scene: { kind: "empty", message: "Nothing is waiting on you" } };
    return {
      v: 1,
      scene: {
        kind: "table",
        columns: [
          { key: "number", label: "#", align: "end" },
          { key: "title", label: "Pull request" }
        ],
        rows: data.rows.slice(0, 10).map((row) => ({ number: row.numbers || "", title: row.titles || "" }))
      }
    };
  }

  // widget.js
  globalThis.render = render;
})();

(() => {
  // src/widgets/missing.ts
  var WHY = {
    "repository-required": "Choose a repository for this tile",
    "not-found": "That repository is not there, or not visible to the plug-in",
    "not-authorized": "The organization has not granted the plug-in this"
  };
  function missing(values) {
    const why = values.unavailable;
    if (!why) return null;
    return { v: 1, scene: { kind: "empty", message: WHY[why] || "There is nothing to show" } };
  }

  // src/widgets/dependabot-alerts.ts
  function render(data) {
    const nothing = missing(data.values);
    if (nothing) return nothing;
    const counts = {};
    for (const row of data.rows) {
      if (row.severities) counts[row.severities] = (counts[row.severities] || 0) + 1;
    }
    const shown = ["critical", "high", "medium", "low"].filter((severity) => counts[severity]);
    if (!shown.length) return { v: 1, scene: { kind: "empty", message: "No open Dependabot alerts" } };
    return {
      v: 1,
      scene: {
        kind: "series",
        mark: "bar",
        series: [
          {
            name: "Alerts",
            points: shown.map((severity) => ({ x: severity.charAt(0).toUpperCase() + severity.slice(1), y: counts[severity] }))
          }
        ]
      }
    };
  }

  // widget.js
  globalThis.render = render;
})();

(() => {
  // src/widgets/missing.ts
  var WHY = {
    "repository-required": "Choose a repository for this tile",
    "not-found": "That repository is not there, or not visible to the plug-in",
    "not-authorized": "The organization has not granted the plug-in this"
  };
  function missing(values) {
    const why = values.unavailable;
    if (!why) return null;
    return { v: 1, scene: { kind: "empty", message: WHY[why] || "There is nothing to show" } };
  }

  // src/widgets/issue-throughput.ts
  function render(data) {
    const nothing = missing(data.values);
    if (nothing) return nothing;
    const days = {};
    const bucket = (iso) => {
      const day = String(iso).slice(0, 10);
      if (!days[day]) days[day] = { opened: 0, closed: 0 };
      return days[day];
    };
    for (const row of data.rows) {
      if (row.created_at) bucket(row.created_at).opened += 1;
      if (row.closed_at) bucket(row.closed_at).closed += 1;
    }
    const ordered = Object.keys(days).sort();
    if (!ordered.length) return { v: 1, scene: { kind: "empty", message: "Nothing opened or closed in this window" } };
    return {
      v: 1,
      scene: {
        kind: "series",
        mark: "line",
        series: [
          { name: "Opened", points: ordered.map((day) => ({ x: day, y: days[day].opened })) },
          { name: "Closed", points: ordered.map((day) => ({ x: day, y: days[day].closed })) }
        ]
      }
    };
  }

  // widget.js
  globalThis.render = render;
})();
